Method.Source:
/// <summary>
/// Create new object
/// </summary>
protected void new()
{
}

/// <summary>
/// Constructs a new instance of <c>METTAMRebateDealPostingProfileForm</c> class.
/// </summary>
/// <returns>
/// A <c>METTAMRebateDealPostingProfileForm</c> class.
/// </returns>
public static METTAMRebateDealPostingProfileForm construct()
{
    return new METTAMRebateDealPostingProfileForm();
}

/// <summary>
/// Provides a lookup for the <c>TAMRebatePosting</c> table
/// </summary>
/// <param name = "_callingControl">
/// The form string control object with which to perform the lookup.
/// </param>
public void rebatePostingProfileId_OnLookup(FormStringControl _callingControl)
{
    TAMRebateDeal tamRebateDeal;
    TAMRebateTable  tamRebateTable;

    if (_callingControl)
    {
        tamRebateDeal = _callingControl.formRun().dataSource(formDataSourceStr(TAMRebateDeal,TAMRebateDeal)).cursor();
        tamRebateTable = _callingControl.formRun().dataSource(formDataSourceStr(TAMRebateDeal,tamRebateTable)).cursor();

        FormComboBoxControl supplierRebateBasis = _callingControl.formRun().design().controlName(formControlStr(TAMRebateDeal, Vend_RebateBasisVend));
        str rebateposting;

        if (supplierRebateBasis)
        {
            rebateposting = supplierRebateBasis.valueStr();
        }

        if (tamRebateDeal && tamRebateDeal.ModuleInventCustVend == ModuleInventCustVend::Vend
            && tamRebateDeal.RebateType == TAMRebateType::Rebate
            && tamRebateDeal.RebateReconciliation == TAMRebateReconciliation::Line
            && (tamRebateTable.RebateBasisVend == TAMRebateBasisVend::Sales
            || supplierRebateBasis.valueStr() == enum2Str(TAMRebateBasisVend::Sales)))
        {
            Query query = new Query();
            QueryBuildDataSource queryBuildDataSource;
            SysTableLookup sysTableLookup;

            sysTableLookup = SysTableLookup::newParameters(tableNum(TAMRebatePosting), _callingControl);
            queryBuildDataSource = query.addDataSource(tableNum(TAMRebatePosting));
            queryBuildDataSource.addRange(fieldNum(TAMRebatePosting, ModuleInventCustVend)).value(SysQuery::value(ModuleInventCustVend::Vend));
            queryBuildDataSource.addRange(fieldNum(TAMRebatePosting, RebateType)).value(SysQuery::value(TAMRebateType::Rebate));

            sysTableLookup.addLookupField(fieldNum(TAMRebatePosting, RebateType));
            sysTableLookup.addLookupField(fieldNum(TAMRebatePosting, ModuleInventCustVend));
            sysTableLookup.addLookupField(fieldNum(TAMRebatePosting, RebatePostingId), true);
            sysTableLookup.addLookupField(fieldNum(TAMRebatePosting, Description));

            sysTableLookup.parmQuery(query);
            sysTableLookup.performFormLookup();
        }
        else
        {
            Query query = TAMRebateDeal::buildLookupPostingProfileQuery(tamRebateDeal, _callingControl);

            SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(TAMRebatePosting), _callingControl);

            sysTableLookup.addLookupfield(fieldNum(TAMRebatePosting, RebatePostingId), true);
            sysTableLookup.addLookupfield(fieldNum(TAMRebatePosting, Description));
            sysTableLookup.addLookupfield(fieldNum(TAMRebatePosting, RebateType));

            sysTableLookup.parmQuery(query);

            sysTableLookup.performFormLookup();
        }
    }


}
